@startuml

class Library {
  + LibraryCode : string
}

class User {
  + Name : string
  + ContactInfo : string
  + SecurityDeposit : float
}

class BorrowableItem {
  + LibraryCode : string
  + Location : string
}

class Book extends BorrowableItem {
  + Publisher : string
}

class Author {
  + Name : string
}

class MagazineIssue extends BorrowableItem {
  + PublicationDate : date
  + Publisher : string
}

class MusicCD extends BorrowableItem {
  + Publisher : string
  + Artist : string
}

class Film extends BorrowableItem {
  + Duration : int
  + Publisher : string
}

class VHS extends Film {}

class DVD extends Film {}

class Actor {
  + Name : string
}

class Loan {
  + DueDate : date
}

class ItemRequest {
  + RequestDate : date
}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
Library "1" -- "*" ItemRequest : receives

User "0..1" -- "*" Loan : borrows
BorrowableItem "1" -- "0..1" Loan : is lent to

Book "*" -- "1..*" Author : written by
Film "*" -- "1..*" Actor : features

@enduml

